// xrpl-proxy/server.js — secure XRPL + Chat + Resend Support Email proxy
const express = require("express");
const axios = require("axios");
const cors = require("cors");
const crypto = require("crypto");
const { rateLimit } = require("express-rate-limit");
const rpcPolicy = require("./rpc-policy.cjs");

const app = express();
const PORT = process.env.PORT || 10000;

app.set("trust proxy", 1);

// ===== XRPL (no API key required) =====
const XRPL_RPC = "https://s1.ripple.com:51234";

// ===== OpenAI config (set in Render env) =====
const OPENAI_KEY = String(process.env.OPENAI_API_KEY || "").trim();
const OPENAI_MODEL = String(
  process.env.OPENAI_MODEL || "gpt-4o-mini"
).trim();

const OPENAI_BASE = String(
  process.env.OPENAI_BASE_URL || "https://api.openai.com/v1"
).replace(/\/+$/, "");

// ===== Resend support email config (set in Render env) =====
const RESEND_API_KEY = String(
  process.env.RESEND_API_KEY || ""
).trim();

const RESEND_API_URL = "https://api.resend.com/emails";

const SUPPORT_EMAIL_TO = String(
  process.env.SUPPORT_EMAIL_TO ||
    "xrbitcoincash@gmail.com"
).trim();

const SUPPORT_EMAIL_FROM = String(
  process.env.SUPPORT_EMAIL_FROM ||
    "XRBitcoinCash Support <support@xrbitcoincash.com>"
).trim();

const SUPPORT_ALLOWED_ORIGINS = new Set(
  String(
    process.env.SUPPORT_ALLOWED_ORIGINS ||
      "https://xrbitcoincash.com,https://www.xrbitcoincash.com"
  )
    .split(",")
    .map((value) => value.trim())
    .filter(Boolean)
);

// Maximum five support submissions per IP every 15 minutes.
const SUPPORT_RATE_WINDOW_MS = 15 * 60 * 1000;
const SUPPORT_RATE_MAX = 5;
const supportRateBuckets = new Map();

const SUPPORT_ISSUE_TYPES = new Set([
  "Page or interface problem",
  "Xaman connection or transaction request",
  "XRBC trustline or transaction",
  "Risk Lens, auditor, or analysis result",
  "Liquidity or market data",
  "Security concern",
  "XRBitcoin ecosystem",
  "General project question"
]);

class SupportValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = "SupportValidationError";
  }
}

// ===== Middleware =====

// Existing public CORS behavior is preserved for XRPL and chat.
// The support route also performs its own strict origin check.
app.use(cors());

app.use(
  express.json({
    limit: "1mb"
  })
);

app.use((req, _res, next) => {
  console.log(`[REQ] ${req.method} ${req.path}`);
  next();
});

// Public evidence traffic is bounded separately from signed-wallet API sessions.
const publicReadLimit = rateLimit({
  windowMs: 60000, limit: 180, standardHeaders: true, legacyHeaders: false,
  message: {result:{status:'error',error:'rate_limit',error_message:'Public request limit reached. Honor Retry-After.'}}
});
app.use('/api/xrpl', publicReadLimit);

// ===== Shared helpers =====

async function xrplRpc(body) {
  const response = await axios.post(
    XRPL_RPC,
    body,
    {
      headers: {
        "Content-Type": "application/json"
      },
      timeout: 20000
    }
  );

  return response.data;
}

function cleanText(value, maxLength) {
  return String(
    value == null
      ? ""
      : value
  )
    .replace(/\u0000/g, "")
    .trim()
    .slice(0, maxLength);
}

function escapeHtml(value) {
  return String(
    value == null
      ? ""
      : value
  )
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function isReplyEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/i.test(
    value
  );
}

function isXHandle(value) {
  return /^@[A-Za-z0-9_]{1,15}$/.test(
    value
  );
}

function supportEmailConfigured() {
  return Boolean(
    RESEND_API_KEY &&
      SUPPORT_EMAIL_TO &&
      SUPPORT_EMAIL_FROM
  );
}

function supportOriginAllowed(req) {
  const origin = cleanText(
    req.get("origin"),
    300
  );

  return Boolean(
    origin &&
      SUPPORT_ALLOWED_ORIGINS.has(origin)
  );
}

function supportRateLimit(
  req,
  res,
  next
) {
  const now = Date.now();

  const ip = cleanText(
    req.ip ||
      req.socket?.remoteAddress ||
      "unknown",
    120
  );

  if (
    supportRateBuckets.size >
    5000
  ) {
    for (
      const [
        key,
        bucket
      ] of supportRateBuckets.entries()
    ) {
      if (
        now >=
        bucket.resetAt
      ) {
        supportRateBuckets.delete(
          key
        );
      }
    }
  }

  const bucket =
    supportRateBuckets.get(ip);

  if (
    !bucket ||
    now >= bucket.resetAt
  ) {
    supportRateBuckets.set(
      ip,
      {
        count: 1,
        resetAt:
          now +
          SUPPORT_RATE_WINDOW_MS
      }
    );

    return next();
  }

  if (
    bucket.count >=
    SUPPORT_RATE_MAX
  ) {
    res.set(
      "Retry-After",
      String(
        Math.ceil(
          (
            bucket.resetAt -
            now
          ) / 1000
        )
      )
    );

    return res
      .status(429)
      .json({
        ok: false,
        message:
          "Too many support requests. Please wait before trying again."
      });
  }

  bucket.count += 1;

  return next();
}

function validateSupportRequest(
  body
) {
  const data = {
    issueType: cleanText(
      body?.issueType,
      90
    ),

    replyContact: cleanText(
      body?.replyContact,
      180
    ),

    pageName: cleanText(
      body?.pageName,
      160
    ),

    publicEvidence: cleanText(
      body?.publicEvidence,
      180
    ),

    problem: cleanText(
      body?.problem,
      5000
    ),

    website: cleanText(
      body?.website,
      200
    ),

    source: cleanText(
      body?.source,
      80
    ),

    pageUrl: cleanText(
      body?.pageUrl,
      500
    ),

    securityAcknowledged:
      body?.securityAcknowledged ===
      true,

    formStartedAt:
      Number(
        body?.formStartedAt
      ),

    submittedAt:
      Number(
        body?.submittedAt
      )
  };

  if (
    !SUPPORT_ISSUE_TYPES.has(
      data.issueType
    )
  ) {
    throw new SupportValidationError(
      "Choose a valid issue type."
    );
  }

  if (
    !data.replyContact ||
    (
      !isReplyEmail(
        data.replyContact
      ) &&
      !isXHandle(
        data.replyContact
      )
    )
  ) {
    throw new SupportValidationError(
      "Enter a valid reply email address or X handle."
    );
  }

  if (
    data.problem.length <
    20
  ) {
    throw new SupportValidationError(
      "Describe the problem using at least 20 characters."
    );
  }

  if (
    !data.securityAcknowledged
  ) {
    throw new SupportValidationError(
      "The security acknowledgment is required."
    );
  }

  const now = Date.now();

  if (
    !Number.isFinite(
      data.formStartedAt
    ) ||
    data.formStartedAt >
      now ||
    now -
      data.formStartedAt <
      2000 ||
    now -
      data.formStartedAt >
      24 *
        60 *
        60 *
        1000
  ) {
    throw new SupportValidationError(
      "The form session could not be verified. Reload the page and try again."
    );
  }

  return data;
}

function makeSupportRequestId() {
  const date = new Date()
    .toISOString()
    .slice(0, 10)
    .replace(/-/g, "");

  const random =
    crypto
      .randomBytes(4)
      .toString("hex")
      .toUpperCase();

  return `XRBC-${date}-${random}`;
}

function buildSupportEmail(
  data,
  requestId,
  userAgent
) {
  const subjectPage =
    data.pageName
      ? ` — ${data.pageName
          .replace(
            /[\r\n]+/g,
            " "
          )
          .slice(0, 80)}`
      : "";

  const subject =
    `[${requestId}] ` +
    `XRBitcoinCash Support — ` +
    `${data.issueType}` +
    `${subjectPage}`;

  const text = [
    "XRBitcoinCash Support Request",
    "==============================",
    "",
    `Reference: ${requestId}`,
    `Issue type: ${data.issueType}`,
    `Reply contact: ${data.replyContact}`,
    `Page or xApp: ${
      data.pageName ||
      "Not supplied"
    }`,
    `Transaction hash or public XRPL address: ${
      data.publicEvidence ||
      "Not supplied"
    }`,
    `Source page: ${
      data.pageUrl ||
      "Not supplied"
    }`,
    `Form source: ${
      data.source ||
      "Not supplied"
    }`,
    "",
    "Problem",
    "-------",
    data.problem,
    "",
    "Security acknowledgment: confirmed.",
    `Browser user agent: ${userAgent}`
  ].join("\n");

  const html = `
    <h2>
      XRBitcoinCash Support Request
    </h2>

    <p>
      <strong>
        Reference:
      </strong>
      ${escapeHtml(
        requestId
      )}
    </p>

    <table
      cellpadding="7"
      cellspacing="0"
      border="1"
      style="border-collapse:collapse"
    >
      <tr>
        <th align="left">
          Issue type
        </th>

        <td>
          ${escapeHtml(
            data.issueType
          )}
        </td>
      </tr>

      <tr>
        <th align="left">
          Reply contact
        </th>

        <td>
          ${escapeHtml(
            data.replyContact
          )}
        </td>
      </tr>

      <tr>
        <th align="left">
          Page or xApp
        </th>

        <td>
          ${escapeHtml(
            data.pageName ||
              "Not supplied"
          )}
        </td>
      </tr>

      <tr>
        <th align="left">
          Public evidence
        </th>

        <td>
          ${escapeHtml(
            data.publicEvidence ||
              "Not supplied"
          )}
        </td>
      </tr>

      <tr>
        <th align="left">
          Source page
        </th>

        <td>
          ${escapeHtml(
            data.pageUrl ||
              "Not supplied"
          )}
        </td>
      </tr>

      <tr>
        <th align="left">
          Form source
        </th>

        <td>
          ${escapeHtml(
            data.source ||
              "Not supplied"
          )}
        </td>
      </tr>
    </table>

    <h3>
      Problem
    </h3>

    <p style="white-space:pre-wrap">
      ${escapeHtml(
        data.problem
      )}
    </p>

    <p>
      <strong>
        Security acknowledgment:
      </strong>
      confirmed.
    </p>
  `;

  return {
    subject,
    text,
    html
  };
}

async function sendSupportEmailWithResend({
  data,
  requestId,
  subject,
  text,
  html
}) {
  const emailPayload = {
    from:
      SUPPORT_EMAIL_FROM,

    to: [
      SUPPORT_EMAIL_TO
    ],

    subject,

    text,

    html,

    headers: {
      "X-XRBC-Support-ID":
        requestId
    }
  };

  /*
   * When the user supplies an
   * email address, the Reply
   * button will answer that address.
   *
   * X handles remain visible in
   * the message body but are not
   * placed into reply_to.
   */
  if (
    isReplyEmail(
      data.replyContact
    )
  ) {
    emailPayload.reply_to =
      data.replyContact;
  }

  const response =
    await axios.post(
      RESEND_API_URL,
      emailPayload,
      {
        headers: {
          Authorization:
            `Bearer ${RESEND_API_KEY}`,

          "Content-Type":
            "application/json",

          "User-Agent":
            "XRBitcoinCash-Support/1.0",

          "Idempotency-Key":
            requestId
        },

        timeout:
          30000,

        validateStatus:
          () => true
      }
    );

  if (
    response.status <
      200 ||
    response.status >=
      300
  ) {
    const resendMessage =
      cleanText(
        response.data
          ?.message ||
          response.data
            ?.error ||
          `Resend returned HTTP ${response.status}.`,
        500
      );

    const error =
      new Error(
        resendMessage
      );

    error.code =
      cleanText(
        response.data
          ?.name ||
          response.data
            ?.code ||
          "RESEND_API_ERROR",
        100
      );

    error.responseCode =
      response.status;

    throw error;
  }

  const resendEmailId =
    cleanText(
      response.data?.id,
      200
    );

  if (!resendEmailId) {
    const error =
      new Error(
        "Resend accepted the request but did not return an email ID."
      );

    error.code =
      "INVALID_RESEND_RESPONSE";

    throw error;
  }

  return resendEmailId;
}

// ===== Health =====

app.get(
  "/healthz",
  (_req, res) => {
    res.json({
      ok: true,

      ts:
        Date.now(),

      supportEmailProvider:
        "resend",

      supportEmailConfigured:
        supportEmailConfigured()
    });
  }
);

// ===== Generic XRPL passthrough =====

app.post(
  "/",
  publicReadLimit,
  rpcPolicy.middleware,
  async (req, res) => {
    try {
      const data =
        await xrplRpc(
          req.body
        );

      res.json(data);
    } catch (err) {
      console.error(
        "generic proxy error:",
        err?.response
          ?.status,
        err?.message
      );

      res
        .status(502)
        .json({
          error:
            "Proxy request failed",

          detail:
            err?.message ||
            String(err)
        });
    }
  }
);

