// ===== XRBitcoinCash support email through Resend HTTPS =====

app.post(
  "/api/support/email",
  supportRateLimit,
  async (req, res) => {
    res.set({
      "Cache-Control":
        "no-store",

      "X-Content-Type-Options":
        "nosniff"
    });

    if (
      !supportOriginAllowed(
        req
      )
    ) {
      return res
        .status(403)
        .json({
          ok: false,

          message:
            "This support endpoint only accepts requests from the official XRBitcoinCash website."
        });
    }

    const requestId =
      makeSupportRequestId();

    try {
      const data =
        validateSupportRequest(
          req.body
        );

      /*
       * Hidden spam honeypot.
       * Bots filling this field
       * receive a neutral success
       * response, but no email is sent.
       */
      if (data.website) {
        return res
          .status(202)
          .json({
            ok: true,
            requestId
          });
      }

      if (
        !supportEmailConfigured()
      ) {
        return res
          .status(503)
          .json({
            ok: false,

            message:
              "The support email service is not configured yet."
          });
      }

      const userAgent =
        cleanText(
          req.get(
            "user-agent"
          ),
          350
        ) ||
        "Not supplied";

      const {
        subject,
        text,
        html
      } =
        buildSupportEmail(
          data,
          requestId,
          userAgent
        );

      const resendEmailId =
        await sendSupportEmailWithResend({
          data,
          requestId,
          subject,
          text,
          html
        });

      console.log(
        "[support email sent]",
        {
          requestId,
          provider:
            "resend",
          resendEmailId
        }
      );

      return res
        .status(200)
        .json({
          ok: true,
          requestId,
          provider:
            "resend"
        });
    } catch (err) {
      const isValidationError =
        err instanceof
          SupportValidationError;

      const message =
        cleanText(
          err?.message ||
            "Unknown error",
          500
        );

      if (
        !isValidationError
      ) {
        console.error(
          "[support email error]",
          {
            requestId,

            provider:
              "resend",

            code:
              err?.code ||
              "",

            responseCode:
              err?.responseCode ||
              err?.response
                ?.status ||
              "",

            message
          }
        );
      }

      return res
        .status(
          isValidationError
            ? 400
            : 502
        )
        .json({
          ok: false,

          message:
            isValidationError
              ? message
              : "The support request could not be delivered. Use the manual email fallback or try again later."
        });
    }
  }
);

// ===== Chat proxy =====

app.post(
  "/chat",
  async (req, res) => {
    try {
      const {
        messages
      } =
        req.body || {};

      if (
        !Array.isArray(
          messages
        ) ||
        messages.length ===
          0
      ) {
        return res
          .status(400)
          .json({
            error:
              "Missing or invalid messages array"
          });
      }

      if (!OPENAI_KEY) {
        return res
          .status(500)
          .json({
            error:
              "OpenAI key not configured on server"
          });
      }

      const trimmed =
        messages.slice(-10);

      const payload = {
        model:
          OPENAI_MODEL,

        messages:
          trimmed,

        temperature:
          0.6,

        max_tokens:
          600
      };

      const response =
        await axios.post(
          `${OPENAI_BASE}/chat/completions`,
          payload,
          {
            headers: {
              Authorization:
                `Bearer ${OPENAI_KEY}`,

              "Content-Type":
                "application/json"
            },

            timeout:
              30000,

            validateStatus:
              () => true
          }
        );

      if (
        response.status ===
        401
      ) {
        return res
          .status(502)
          .json({
            error:
              "OpenAI auth failed (401)",

            detail:
              response.data
          });
      }

      if (
        response.status ===
        429
      ) {
        return res
          .status(502)
          .json({
            error:
              "OpenAI rate limit / insufficient quota (429)",

            detail:
              response.data
          });
      }

      if (
        response.status <
          200 ||
        response.status >=
          300
      ) {
        console.error(
          "[OpenAI error]",
          response.status,
          response.data
        );

        return res
          .status(502)
          .json({
            error:
              "Upstream OpenAI error",

            status:
              response.status,

            detail:
              response.data
          });
      }

      if (
        !response.data ||
        typeof response.data !==
          "object"
      ) {
        return res
          .status(502)
          .json({
            error:
              "Invalid OpenAI response format"
          });
      }

      res.json(
        response.data
      );
    } catch (err) {
      console.error(
        "[chat proxy error]",
        err?.message ||
          err
      );

      res
        .status(502)
        .json({
          error:
            "Chat proxy request failed",

          detail:
            err?.message ||
            String(err)
        });
    }
  }
);

// ===== Environment check =====
