app.use('/api/v1', require('./api-v1.cjs').createApi({ rpcUrl: XRPL_RPC }));
app.use('/api/v1', (error, req, res, next) => {
  if (!error) return next();
  const status = error.type === 'entity.too.large' ? 413 : error.type === 'entity.parse.failed' ? 400 : 500;
  res.status(status).set('Cache-Control', 'no-store').json({
    error: { code: status === 413 ? 'body_too_large' : status === 400 ? 'invalid_json' : 'internal_error',
      message: status === 400 ? 'Use a valid JSON object.' : status === 413 ? 'Request body is too large.' : 'Request could not be completed.' },
    meta: { apiVersion: '1.0.0' }
  });
});

// ===== 404 fallback =====

app.use((req, res) => {
  res
    .status(404)
    .json({
      error:
        "Not found",

      path:
        req.path,

      method:
        req.method
    });
});

// ===== Boot log =====

function printRoutes() {
  const routes = [];

  const stack =
    app._router?.stack ||
    [];

  stack.forEach(
    (middleware) => {
      if (
        middleware.route
      ) {
        routes.push(
          `${Object.keys(
            middleware.route
              .methods
          )
            .join(",")
            .toUpperCase()} ${
            middleware.route
              .path
          }`
        );
      } else if (
        middleware.name ===
          "router" &&
        middleware.handle
          ?.stack
      ) {
        middleware.handle.stack.forEach(
          (
            routeLayer
          ) => {
            if (
              routeLayer.route
            ) {
              routes.push(
                `${Object.keys(
                  routeLayer
                    .route
                    .methods
                )
                  .join(",")
                  .toUpperCase()} ${
                  routeLayer
                    .route
                    .path
                }`
              );
            }
          }
        );
      }
    }
  );

  console.log(
    "[ROUTES]",
    routes
  );
}

